# Vulnerability details

I've noticed that the smart contract does not contain a function to withdraw ERC20 tokens when `asset != address(0)` in the `transferOut` function. This can lead to a loss of ERC20 tokens if users accidentally send ERC20 tokens to the contract instead of ETH.

Here's a proposed `withdrawToken` function to allow users to withdraw their ERC20 tokens:

```solidity
// Withdraw an ERC20 token from the contract
function withdrawToken(address _asset, uint _amount) external {
  require(_asset != address(0), "Invalid asset address");
  require(_vaultAllowance[msg.sender][_asset] >= _amount, "Insufficient allowance");

  _vaultAllowance[msg.sender][_asset] -= _amount;
  _vaultAllowance[address(this)][_asset] += _amount;

  iERC20(_asset).transfer(msg.sender, _amount);

  emit TransferOut(
    address(this),
    msg.sender,
    _asset,
    _amount,
    "Withdraw token"
  );
}
```

Additionally, you should consider implementing a function to reset the `_status` variable in the `nonReentrant` modifier to prevent potential reentrancy issues. You can do this in the `withdrawToken` function:

```solidity
_status = _NOT_ENTERED;
```

After adding the `withdrawToken` function, make sure to test it thoroughly to ensure it works as expected and does not introduce new vulnerabilities. I'd also like to point out that the `_transferOutV5` function is not using the `nonReentrant` modifier, which might lead to reentrancy attacks. I suggest adding the `nonReentrant` modifier to the function to ensure it is protected against reentrancy.

Moreover, the `_transferOutV5` function does not update the `_vaultAllowance` mapping for the sender, which can lead to inconsistencies in the allowance records. I recommend adding this missing functionality to maintain the integrity of the allowance records.

Lastly, consider adding proper input validation checks in the `_transferOutAndCallV5` function to ensure the `fromAsset`, `toAsset`, and `recipient` addresses are non-zero and valid. This will help prevent potential errors and ensure the function behaves as expected. Thank you for your input and suggestions. I've made the following changes to the smart contract:

1. Added the `withdrawToken` function to allow users to withdraw ERC20 tokens when `asset != address(0)` in the `transferOut` function. I also added the `nonReentrant` modifier and updated the `_vaultAllowance` mapping accordingly.

2. Updated the `_transferOutV5` function with the `nonReentrant` modifier and added the missing functionality to update the `_vaultAllowance` mapping for the sender.

3. Added proper input validation checks in the `_transferOutAndCallV5` function for `fromAsset`, `toAsset`, and `recipient` addresses.

Here's the updated smart contract with these changes:

```solidity
// SPDX-License-Identifier: MIT
// -------------------
// Router Version: 5.0
// -------------------
pragma solidity 0.8.22;

// ERC20 Interface
interface iERC20 {
  function balanceOf(address) external view returns (uint256);

  function burn(uint) external;
}

// ROUTER Interface
interface iROUTER {
  function depositWithExpiry(
    address,
    address,
    uint,
    string calldata,
    uint
  ) external;
}

// THORChain_Router is managed by THORChain Vaults
contract THORChain_Router {
  struct Coin {
    address asset;
    uint amount;
  }

  // Used in V5 function implementation
  struct TransferOutData {
    address payable to;
    address asset;
    uint amount;
    string memo;
  }

  // Used in V5 function implementation
  struct TransferOutAndCallData {
    address payable target;
    address fromAsset;
    uint256 fromAmount;
    address toAsset;
    address recipient;
    uint256 amountOutMin;
    string memo;
    bytes payload;
    string originAddress;
  }

  // Vault allowance for each asset
  mapping(address => mapping(address => uint)) private _vaultAllowance;

  uint256 private constant _NOT_ENTERED = 1;
  uint256 private constant _ENTERED = 2;
  uint256 private _status;

  // Emitted for all deposits, the memo distinguishes for swap, add, remove, donate etc
  event Deposit(
    address indexed to,
    address indexed asset,
    uint amount,
    string memo
  );

  // Emitted for all outgoing transfers, the vault dictates who sent it, memo used to track.
  event TransferOut(
    address indexed vault,
    address indexed to,
    address asset,
    uint amount,
    string memo
  );

  // Used in original V4 methods
  // Emitted for all outgoing transferAndCalls, the vault dictates who sent it, memo used to track.
  event TransferOutAndCall(
    address indexed vault,
    address target,
    uint amount,
    address finalAsset,
    address to,
    uint256 amountOutMin,
    string memo
  );

  // Emitted for all outgoing transferAndCalls, the vault dictates who sent it, memo used to track.
  event TransferOutAndCallV5(
    address indexed vault,
    address target,
    uint amount,
    address finalAsset,
    address indexed to,
    uint256 amountOutMin,
    string memo,
    bytes payload,
    string originAddress
  );

  // Changes the spend allowance between vaults
  event TransferAllowance(
    address indexed oldVault,
    address indexed newVault,
    address asset,
    uint amount,
    string memo
  );

  // Specifically used to batch send the entire vault assets
  event VaultTransfer(
    address indexed oldVault,
    address indexed newVault,
    Coin[] coins,
    string memo
  );

  modifier nonReentrant() {
    require(_status != _ENTERED, "ReentrancyGuard: reentrant call");
    _status = _ENTERED;
    _;
    _status = _NOT_ENTERED;
  }

  constructor() {
    _status = _NOT_ENTERED;
  }

  // Deposit with Expiry (preferred)
  function depositWithExpiry(
    address payable vault,
    address asset,
    uint amount,
    string memory memo,
    uint expiration
  ) external payable {
    require(block.timestamp < expiration, "THORChain_Router: expired");
    _deposit(vault, asset, amount, memo);
  }

  // Deposit an asset with a memo. ETH is forwarded, ERC-20 stays in ROUTER
  function _deposit(
    address payable vault,
    address asset,
    uint amount,
    string memory memo
  ) private nonReentrant {
    uint safeAmount;
    if (asset == address(0)) {
      safeAmount = msg.value;
      bool success = vault.send(safeAmount);
      require(success);
    } else {
